using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;
namespace FileCompass {
 // Tracks only handles owned by this process's EXT workers. Never terminates unrelated programs.
 internal static class ExtIoGate {
  static readonly object gate=new object();static readonly Dictionary<string,State> states=new Dictionary<string,State>(StringComparer.OrdinalIgnoreCase);
  internal sealed class State {internal bool Paused;internal readonly HashSet<Lease> Active=new HashSet<Lease>();internal TaskCompletionSource<bool> Drained;}
  internal sealed class Lease:IDisposable {readonly State state;internal readonly CancellationTokenSource Cancellation;internal readonly bool Export;bool disposed;internal CancellationToken Token{get{return Cancellation.Token;}}internal Lease(State state,bool export,CancellationToken token){this.state=state;Export=export;Cancellation=CancellationTokenSource.CreateLinkedTokenSource(token);}public void Dispose(){lock(gate){if(disposed)return;disposed=true;if(state!=null){state.Active.Remove(this);if(state.Active.Count==0&&state.Drained!=null)state.Drained.TrySetResult(true);}Cancellation.Dispose();}}internal void Cancel(){lock(gate){if(!disposed)Cancellation.Cancel();}}}
  sealed class Pause:IDisposable {readonly State state;internal Pause(State state){this.state=state;}public void Dispose(){lock(gate){state.Paused=false;state.Drained=null;}}}
  internal static bool IsPaused(string device){lock(gate){State state;return states.TryGetValue(device,out state)&&state.Paused;}}
  internal static Lease Enter(ExtRequest request,CancellationToken token){lock(gate){State state=null;if(request.Source!=null&&request.Source.Physical){if(!states.TryGetValue(request.Source.Device,out state)){state=new State();states.Add(request.Source.Device,state);}if(state.Paused)throw new IOException(L.Text("usb.busy"));}var lease=new Lease(state,request.Action=="export",token);if(state!=null)state.Active.Add(lease);return lease;}}
  internal static async Task<IDisposable> PauseAsync(ExtSource source){State state;Lease[] pending;Pause pause;Task drained;lock(gate){if(!states.TryGetValue(source.Device,out state)){state=new State();states.Add(source.Device,state);}if(state.Paused||state.Active.Any(x=>x.Export))throw new IOException(L.Text("usb.busy"));state.Paused=true;state.Drained=new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);if(state.Active.Count==0)state.Drained.SetResult(true);pending=state.Active.ToArray();pause=new Pause(state);drained=state.Drained.Task;}try{foreach(var lease in pending)lease.Cancel();if(await Task.WhenAny(drained,Task.Delay(6000))!=drained)throw new IOException(L.Text("usb.busy"));await drained;return pause;}catch{pause.Dispose();throw;}}
 }
}
